mapper.select:
SELECT EXISTS (
    SELECT 1 FROM emoji_reactions er
    JOIN auth.users u ON er.users_id = u.id
    WHERE er.reference_type = CAST(#{data.referenceType} AS emoji_reference_type)
    AND er.reference_id = #{data.referenceId}
    AND er.emoji = #{data.emoji}
    AND u.email = #{email}
)

mapper.delete:
DELETE FROM emoji_reactions
WHERE reference_type = CAST(#{data.referenceType} AS emoji_reference_type)
AND reference_id = #{data.referenceId}
AND emoji = #{data.emoji}
AND users_id IN (SELECT id FROM auth.users WHERE email = #{email});
